  /// Find an [Element] whose widget has a [ValueKey<String>] matching [key].
  static Element? _findElementByKey(String key) {
    final targetKey = ValueKey<String>(key);
    Element? found;
    final root = WidgetsBinding.instance.rootElement;
    if (root == null) return null;
    _walkSubtree(root, (el) {
      if (el.widget.key == targetKey) {
        found = el;
        return true;
      }
      return false;
    }, includeSelf: true);
    return found;
  }

  /// The `onTap` of [el]'s widget (GestureDetector/InkResponse), else null.
  static VoidCallback? _onTapOf(Element el) {
    final w = el.widget;
    if (w is GestureDetector) return w.onTap;
    if (w is InkResponse) return w.onTap;
    return null;
  }

  /// Invoke the first `onTap` found in [root]'s subtree; true if one fired.
  static bool _invokeOnTapInSubtree(Element root) => _walkSubtree(root, (el) {
    final onTap = _onTapOf(el);
    if (onTap != null) {
      onTap();
      return true;
    }
    return false;
  });

  /// Invoke horizontal/vertical drag callbacks on the first matching
  /// [GestureDetector] in [root]'s subtree.
  static bool _invokeDragInSubtree(
    Element root, {
    required Offset startGlobal,
    required double dx,
    required double dy,
    required int steps,
  }) {
    final isHorizontal = dx.abs() >= dy.abs();
    final delta = Offset(dx / steps, dy / steps);
    return _walkSubtree(root, (el) {
      final widget = el.widget;
      if (widget is! GestureDetector) return false;
      final ro = el.findRenderObject();
      if (ro is! RenderBox || !ro.attached || !ro.hasSize || ro.size.isEmpty) {
        return false;
      }

      if (isHorizontal) {
        final onStart = widget.onHorizontalDragStart;
        final onUpdate = widget.onHorizontalDragUpdate;
        final onEnd = widget.onHorizontalDragEnd;
        if (onStart == null || onUpdate == null || onEnd == null) {
          return false;
        }
        onStart(
          DragStartDetails(
            globalPosition: startGlobal,
            localPosition: ro.globalToLocal(startGlobal),
          ),
        );
        var p = startGlobal;
        for (var i = 0; i < steps; i++) {
          p += delta;
          onUpdate(
            DragUpdateDetails(
              globalPosition: p,
              localPosition: ro.globalToLocal(p),
              delta: delta,
              primaryDelta: delta.dx,
            ),
          );
        }
        onEnd(DragEndDetails(primaryVelocity: 0));
        return true;
      }

      final onStart = widget.onVerticalDragStart;
      final onUpdate = widget.onVerticalDragUpdate;
      final onEnd = widget.onVerticalDragEnd;
      if (onStart == null || onUpdate == null || onEnd == null) return false;
      onStart(
        DragStartDetails(
          globalPosition: startGlobal,
          localPosition: ro.globalToLocal(startGlobal),
        ),
      );
      var p = startGlobal;
      for (var i = 0; i < steps; i++) {
        p += delta;
        onUpdate(
          DragUpdateDetails(
            globalPosition: p,
            localPosition: ro.globalToLocal(p),
            delta: delta,
            primaryDelta: delta.dy,
          ),
        );
      }
      onEnd(DragEndDetails(primaryVelocity: 0));
      return true;
    });
